program.source:
Algoritmo Semana
  Dimension temperaturas[7] Como Entero;
  Definir suma Como Entero <- 0;
  Para i <- 0 Hasta 7 Hacer
    Leer temperaturas[i];
    suma <- suma + temperaturas[i];
  FinPara
  Escribir suma;
FinAlgoritmo

